import json,os,socket,sys
try:
    value=os.environ["COPS_EGRESS_BROKER_FD"]
    if not value.isascii() or not value.isdecimal():
        raise ValueError()
    channel=socket.socket(fileno=int(value))
    if channel.family != socket.AF_UNIX or channel.type != socket.SOCK_STREAM:
        raise ValueError()
    channel.getpeername()
    channel.sendall(b'{"version":"cops.web-api-replay/v1","action":"dispatch"}\n')
    payload=b""
    limit=1024
    while not payload.endswith(b"\n"):
        part=channel.recv(min(1024,limit+1-len(payload)))
        if not part:
            raise ValueError()
        payload+=part
        if len(payload)>limit:
            raise ValueError()
    result=json.loads(payload.decode("utf-8"))
    if result != {"status":"completed"}:
        raise ValueError()
    sys.stdout.buffer.write(b'{"status":"completed"}\n')
    sys.stdout.buffer.flush()
except Exception:
    sys.exit(1)
